function renderCompositionControls(p){const host=q('composition-sliders');if(!host)return;host.innerHTML=COMP_KEYS.map(k=>'<div class="composition-row"><label for="comp-'+k+'">'+COMP_LABELS[k]+'</label><input id="comp-'+k+'" data-comp="'+k+'" type="range" min="0" max="100" step="1" value="'+(p.composition[k]||0)+'"><output id="comp-'+k+'-out">'+Math.round(p.composition[k]||0)+'%</output></div>').join('');host.querySelectorAll('[data-comp]').forEach(input=>input.addEventListener('input',()=>{q(input.id+'-out').textContent=Math.round(input.value)+'%';updateCompositionTotal();renderAppearance(readPlanetForm(false));}));updateCompositionTotal();}
