function renderAppearance(p){const host=q('planet-appearance-preview');if(!host||!p)return;const c=p.composition||{},segments=[];let start=0;const color={ocean:'#227db5',land:'#6f8348',ice:'#c8eaf4',mountainousIce:'#f2fbff',gas:'#9fb5c7',volcanic:'#e0502f'};for(const k of COMP_KEYS){const end=start+(Number(c[k])||0)*3.6;segments.push(color[k]+' '+start+'deg '+end+'deg');start=end;}host.innerHTML='<div class="planet-preview-sphere"></div>'+(p.rings&&p.rings.enabled?'<div class="planet-preview-ring"></div>':'');const sphere=host.querySelector('.planet-preview-sphere');if(sphere)sphere.style.setProperty('--planet-preview','conic-gradient('+segments.join(',')+')');const ring=host.querySelector('.planet-preview-ring');if(ring)ring.style.setProperty('--ring-tilt',(p.rings.tiltDeg||0)+'deg');}
