function drawSeasonChart(p,c){const canvas=q('season-chart');if(!canvas)return;const ctx=canvas.getContext('2d'),rows=PC.seasonalSeries(p,state.system.star,90),w=canvas.width,h=canvas.height,pad=44;ctx.clearRect(0,0,w,h);ctx.fillStyle='#05080d';ctx.fillRect(0,0,w,h);const vals=rows.map(r=>r.tempC),min=Math.min(...vals)-5,max=Math.max(...vals)+5;ctx.strokeStyle='rgba(221,251,255,.16)';ctx.lineWidth=1;for(let i=0;i<=5;i++){const y=pad+(h-pad*2)*i/5;ctx.beginPath();ctx.moveTo(pad,y);ctx.lineTo(w-pad,y);ctx.stroke();ctx.fillStyle='#c9f6ff';ctx.font='12px sans-serif';ctx.fillText((max-(max-min)*i/5).toFixed(0)+'°C',4,y+4);}ctx.strokeStyle='#5ee8d5';ctx.lineWidth=3;ctx.beginPath();rows.forEach((r,i)=>{const x=pad+(w-pad*2)*i/(rows.length-1),y=pad+(h-pad*2)*(max-r.tempC)/(max-min);if(i)ctx.lineTo(x,y);else ctx.moveTo(x,y);});ctx.stroke();ctx.fillStyle='#f1be6a';ctx.fillText('0%',pad,h-12);ctx.fillText('25%',pad+(w-pad*2)*.25,h-12);ctx.fillText('50%',pad+(w-pad*2)*.5,h-12);ctx.fillText('75%',pad+(w-pad*2)*.75,h-12);ctx.fillText('100%',w-pad-30,h-12);}
