function createSavepoint(label){state.savepoints.unshift({id:uid('save'),label:label||('Save point '+(state.savepoints.length+1)),createdAt:new Date().toISOString(),epochDay:state.epochDay,snapshot:deep({system:state.system,genre:state.genre,era:state.era,projectName:state.projectName})});state.savepoints=state.savepoints.slice(0,20);save('Created a reversible galaxy save point.');toast('Save point created.');}
