function randomSystem(){const rng=seeded(Date.now()),count=3+Math.floor(rng()*8);state.system.star.massSolar=round(.45+rng()*1.9,2);state.system.star.luminositySolar=round(Math.pow(state.system.star.massSolar,3.5),3);state.system.star.temperatureK=round(3200+state.system.star.massSolar*2800,0);state.system.star.radiusSolar=round(Math.pow(state.system.star.massSolar,.8),2);state.system.planets=[];let a=.18+rng()*.3;for(let i=0;i<count;i++){a*=1.45+rng()*.58;const p=defaultPlanet(i,pick(['Astra','Cyr','Daro','Eli','Fera','Iona','Khar','Lumi','Nox','Oru','Prax','Rhea','Sori','Vela','Zan'],rng)+(i+1),pick(['terrestrial','ocean','ice','desert','lava','gas-giant','ice-giant','fantasy','hybrid'],rng),round(a,3));p.eccentricity=round(rng()*.22,3);p.axialTiltDeg=round(rng()*95,1);if(rng()<.16)p.orbitDirection='retrograde';if(rng()<.35){p.rings.enabled=true;p.rings.tiltDeg=round((rng()-.5)*80,1);}p.moons=generateMoonsFor(p,Math.floor(rng()*(p.type.includes('giant')?12:4)));state.system.planets.push(p);}state.selectedPlanetId=state.system.planets[0].id;save('Generated a new randomized star system.');rebuildScene();selectPlanet(state.selectedPlanetId,false);toast('Random star system generated.');}
