function exportJson(){const blob=new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=(state.projectName||'WorldBuilder_Galaxy').replace(/[^a-z0-9_-]+/gi,'_')+'.worldbuilder.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
